mod common;

use common::Harness;
use serde_json::json;

fn create(h: &mut Harness, name: &str, max: u64) {
    h.ok(json!({"Command": "CreateQueue", "QueueName": name,
                "Attributes": {"MaxMessageBytes": max}}));
}

fn send(h: &mut Harness, body: &str) -> serde_json::Value {
    h.run(json!({"Command": "SendMessage", "QueueName": "q", "Body": body}))
}

#[test]
fn limit_counts_utf8_bytes_and_is_inclusive() {
    let mut h = Harness::new();
    create(&mut h, "q", 4);
    assert_eq!(send(&mut h, "abcd")["ok"], true);
    // "é" is two bytes: 2 + 2 fits, 3 + 2 does not.
    assert_eq!(send(&mut h, "éé")["ok"], true);
    assert_eq!(
        send(&mut h, "abcé")["error"]["code"],
        "InvalidParameterValue"
    );
    assert_eq!(
        send(&mut h, "abcde")["error"]["code"],
        "InvalidParameterValue"
    );
}

#[test]
fn range_and_default() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5"), json!(5.0)] {
        assert_eq!(
            h.err(json!({"Command": "CreateQueue", "QueueName": "q",
                         "Attributes": {"MaxMessageBytes": bad}})),
            "InvalidParameterValue"
        );
    }
    h.ok(json!({"Command": "CreateQueue", "QueueName": "d"}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "d"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1024);
}

#[test]
fn takes_part_in_create_idempotence() {
    let mut h = Harness::new();
    create(&mut h, "q", 10);
    create(&mut h, "q", 10);
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q",
                     "Attributes": {"MaxMessageBytes": 11}})),
        "QueueAlreadyExists"
    );
}

#[test]
fn rule_comes_before_unsupported_operation() {
    let mut h = Harness::new();
    create(&mut h, "q", 2);
    // Both the size rule and the standard-queue GroupId rule apply.
    let r = h.run(json!({"Command": "SendMessage", "QueueName": "q",
                         "Body": "abc", "GroupId": "g"}));
    assert_eq!(r["error"]["code"], "InvalidParameterValue");
}

#[test]
fn change_does_not_touch_existing_messages() {
    let mut h = Harness::new();
    create(&mut h, "q", 10);
    assert_eq!(send(&mut h, "0123456789")["ok"], true);
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 3}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "0123456789");
    assert_eq!(send(&mut h, "0123")["error"]["code"], "InvalidParameterValue");
    assert_eq!(
        h.err(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                     "Attributes": {"MaxMessageBytes": 0}})),
        "InvalidParameterValue"
    );
}

#[test]
fn dead_letter_moves_ignore_the_limit() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "dead",
                "Attributes": {"MaxMessageBytes": 1}}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
                "Attributes": {"DeadLetterQueue": "dead", "MaxReceiveCount": 1,
                               "VisibilityTimeout": 0}}));
    assert_eq!(send(&mut h, "long body")["ok"], true);
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dead"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
}
E
